CREATE QUEUE "modular_requests_a" ( ID BIGINT NOT NULL , ACCOUNT_ID BIGINT NOT NULL , AMOUNT BIGINT NOT NULL , NOTE TEXT NOT NULL );
CREATE TABLE "modular_accounts_a" ( ID BIGINT PRIMARY KEY , ACTIVE BOOLEAN NOT NULL , TIER TEXT NOT NULL , CREDIT_LIMIT BIGINT NOT NULL );
CREATE TABLE "modular_ledger_a" ( ID BIGINT PRIMARY KEY , ACCOUNT_ID BIGINT NOT NULL , AMOUNT BIGINT NOT NULL , SUMMARY TEXT NOT NULL );
CREATE STREAM "modular_events_a" ( ID BIGINT NOT NULL , ACCOUNT_ID BIGINT NOT NULL , SUMMARY TEXT NOT NULL );
CREATE QUEUE "modular_followup_a" ( ID BIGINT NOT NULL , ACCOUNT_ID BIGINT NOT NULL , SUMMARY TEXT NOT NULL );
INSERT INTO "modular_accounts_a" VALUES ( 7 , TRUE , 'gold' , 5000 ) , ( 8 , FALSE , 'standard' , 1000 ) , ( 9 , TRUE , 'standard' , 500 );
CREATE DATAFLOW "modular_orders_a" FROM QUEUE "modular_requests_a" AS order_item WHERE order_item.amount > 0 AND order_item.amount <= 1000000 AS BEGIN BEGIN ATOMIC LET found_account = SELECT id, active, tier, credit_limit FROM "modular_accounts_a" WHERE id = order_item.account_id; REQUIRE found_account IS NOT NULL AND found_account.id = order_item.account_id ELSE 'MissingAccount'; REQUIRE found_account.active ELSE 'InactiveAccount'; REQUIRE found_account.tier = 'gold' OR found_account.tier = 'standard' ELSE 'UnsupportedTier'; REQUIRE order_item.amount <= found_account.credit_limit ELSE 'CreditLimitExceeded'; LET caller_sentinel = 'caller-local-shadow-sentinel'; LET generated_token = RANDOM_TOKEN(16); REQUIRE generated_token = generated_token ELSE 'ImpureTokenMismatch'; LET cleaned = CASE WHEN order_item.note = '' THEN 'empty' ELSE CASE WHEN order_item.note = 'priority' THEN 'priority-note' ELSE order_item.note END END; LET computed_summary = (CASE WHEN order_item.amount >= 1000 THEN 'large' ELSE CASE WHEN order_item.amount >= 100 THEN 'medium' ELSE 'small' END END) || ':' || (CASE WHEN order_item.amount >= 1000 AND cleaned = 'empty' THEN 'review' ELSE CASE WHEN order_item.amount >= 1000 THEN 'elevated' ELSE CASE WHEN cleaned = 'priority-note' THEN 'expedited' ELSE 'routine' END END END) || ':' || cleaned || ':' || (CASE WHEN order_item.amount >= 1000 THEN 'window=institutional-clearance-corridor-v1/band=large/ledger-policy=primary-verified-settlement-lane-alpha-01' ELSE CASE WHEN order_item.amount >= 100 THEN 'window=commercial-clearance-corridor-v1/band=medium/ledger-policy=standard-verified-settlement-lane-beta-02' ELSE 'window=retail-micro-clearance-corridor-v1/band=small/ledger-policy=automated-verified-settlement-lane-gamma-03' END END) || '|' || (CASE WHEN order_item.amount >= 1000 THEN 'schedule=tier-alpha/corridor=priority-wire-settlement-profile-v1/settlement-class=institutional-high-value-order' ELSE CASE WHEN order_item.amount >= 250 THEN 'schedule=tier-beta/corridor=standard-commercial-settlement-profile-v1/settlement-class=commercial-mid-value-order' ELSE 'schedule=tier-gamma/corridor=economy-batch-settlement-profile-v1/settlement-class=automated-low-value-order-lane' END END) || '|' || (CASE WHEN order_item.amount >= 1000 THEN 'compliance=dual-control-ledger-stream-followup-atomic-v1/hygiene=lexical-frame-isolated/audit-band=institutional' ELSE CASE WHEN order_item.amount >= 100 THEN 'compliance=verified-account-tier-credit-guard-atomic-v1/hygiene=lexical-frame-isolated/audit-band=commercial-std' ELSE 'compliance=automated-account-guard-atomic-settlement-v1/hygiene=lexical-frame-isolated/audit-band=retail-standard' END END); INSERT INTO "modular_ledger_a" VALUES (order_item.id, order_item.account_id, order_item.amount, computed_summary) ON CONFLICT (id) DO ASSERT SAME ROW; PRODUCE INTO "modular_events_a" VALUES (order_item.id, order_item.account_id, computed_summary); ENQUEUE INTO "modular_followup_a" VALUES (order_item.id, order_item.account_id, computed_summary); LET settled = order_item.id; REQUIRE settled = order_item.id ELSE 'WrongReturnedOrder'; REQUIRE caller_sentinel = 'caller-local-shadow-sentinel' AND order_item.note <> 'rollback_after_call' ELSE 'PostCallRejected'; END; END;
AUTHORIZE DATAFLOW "modular_orders_a" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "modular_orders_a";
CREATE TABLE "modular_dispatched_a" ( ID BIGINT PRIMARY KEY , ACCOUNT_ID BIGINT NOT NULL , SUMMARY TEXT NOT NULL );
CREATE DATAFLOW "modular_dispatch_a" FROM QUEUE "modular_followup_a" AS queued AS BEGIN BEGIN ATOMIC INSERT INTO "modular_dispatched_a" VALUES (queued.id, queued.account_id, queued.summary) ON CONFLICT (id) DO ASSERT SAME ROW; END; END;
AUTHORIZE DATAFLOW "modular_dispatch_a" AS ROLE CURRENT_ROLE;
ACTIVATE DATAFLOW "modular_dispatch_a";
