eta/corridor=standard-commercial-settlement-profile-v1/settlement-class=commercial-mid-value-order' ELSE 'schedule=tier-gamma/corridor=economy-batch-settlement-profile-v1/settlement-class=automated-low-value-order-lane' END END) || '|' || (CASE WHEN order_item.amount >= 1000 THEN 'compliance=dual-control-ledger-stream-followup-atomic-v1/hygiene=lexical-frame-isolated/audit-band=institutional' ELSE CASE WHEN order_item.amount >= 100 THEN 'compliance=verified-account-tier-credit-guard-atomic-v1/hygiene=lexical-frame-isolated/audit-band=commercial-std' ELSE 'compliance=automated-account-guard-atomic-settlement-v1/hygiene=lexical-frame-isolated/audit-band=retail-standard' END END); INSERT INTO "modular_ledger_b" VALUES (order_item.id, order_item.account_id, order_item.amount, computed_summary) ON CONFLICT (id) DO ASSERT SAME ROW; PRODUCE INTO "modular_events_b" VALUES (order_item.id, order_item.account_id, computed_summary); ENQUEUE INTO "modular_followup_b" VALUES (order_item.id, order_item.account_id, computed_summary); LET settled = order_item.id; REQUIRE settled = order_item.id ELSE 'WrongReturnedOrder'; REQUIRE caller_sentinel = 'caller-local-shadow-sentinel' AND order_item.note <> 'rollback_after_call' ELSE 'PostCallRejected'; END; END;
